const std=@import("std");const M=@import("simulation/microbes.zig");const H=@import("habitat_feedback.zig");
noinline fn call(cells:[]M.Cell)i32{return H.originStage(cells);}
fn bench(label:[]const u8,cells:[]M.Cell)!void{
 var timer=try std.time.Timer.start();var checksum:u64=0;
 for(0..1000)|_|{std.mem.doNotOptimizeAway(cells.ptr);checksum+=@intCast(call(cells));}
 const ns=timer.read();std.debug.print("ORIGIN_STAGE case={s} cells={d} calls=1000 mean_us={d:.3} checksum={d}\n",.{label,cells.len,@as(f64,@floatFromInt(ns))/1000000,checksum});
}
